function longestCleanRun(nums: number[]): number {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    let used = 0, j = i;
    while (j < nums.length && (used & nums[j]) === 0) used |= nums[j++];
    best = Math.max(best, j - i);
  }
  return best;
}

