class Solution:
    def longestCleanRun(self, nums: List[int]) -> int:
        best = 0
        for i in range(len(nums)):
            used, j = 0, i
            while j < len(nums) and used & nums[j] == 0:
                used |= nums[j]
                j += 1
            best = max(best, j - i)
        return best

