function longestCleanRun(nums: number[]): number {
  let lo = 0, used = 0, best = 0;
  for (let hi = 0; hi < nums.length; hi++) {
    while ((used & nums[hi]) !== 0) used ^= nums[lo++];
    used |= nums[hi];
    best = Math.max(best, hi - lo + 1);
  }
  return best;
}

